@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final UserRepository userRepository;

    public OrderService(OrderRepository orderRepository, UserRepository userRepository) {
        this.orderRepository = orderRepository;
        this.userRepository = userRepository;
    }

    @Transactional
    public void createOrder(Long userId, BigDecimal amount) {
        // Optimization: Use getReferenceById to avoid a SELECT query for the User
        // We only need the reference to set the foreign key on the Order entity.
        User userProxy = userRepository.getReferenceById(userId);

        Order order = new Order();
        order.setUser(userProxy);
        order.setTotalAmount(amount);

        orderRepository.save(order);
    }

    @Transactional(readOnly = true)
    public UserDetailsDTO getUserDetails(Long userId) {
        // Use findById when we actually need to inspect the entity's fields immediately
        User user = userRepository.findById(userId)
            .orElseThrow(() -> new EntityNotFoundException("User not found"));

        return new UserDetailsDTO(user.getUsername(), user.getEmail());
    }
}
